"use client";

import React from 'react';
import {
    Star,
    MessageCircle,
    ThumbsUp,
    User,
    Calendar,
    Scissors,
    Quote,
    Filter,
    ChevronDown,
    Award
} from 'lucide-react';
import { Button } from '@/components/ui/Button';

// Mock Ratings Data
const ratings = [
    { id: 1, client: 'Rodrigo Lima', date: 'há 1 hora', stars: 5, comment: 'O Marcelo é sensacional, melhor degradê da região. Além do corte, o papo é sempre nota 10!', service: 'Corte Degradê' },
    { id: 2, client: 'Gabriel Souza', date: 'há 1 dia', stars: 5, comment: 'Pontual e muito técnico. A barbearia está de parabéns pelo profissional.', service: 'Combo Premium' },
    { id: 3, client: 'Fernando Costa', date: 'há 3 dias', stars: 4, comment: 'Muito bom o corte, só achei que demorou um pouquinho a mais do previsto, mas o resultado compensou.', service: 'Corte Social' },
    { id: 4, client: 'André Silva', date: 'há 1 semana', stars: 5, comment: 'Sem palavras, serviço de excelência. Recomendo de olhos fechados!', service: 'Barba Terapêutica' },
];

export default function BarberRatings() {
    return (
        <div className="max-w-4xl mx-auto space-y-10 animate-fade-in-up">
            <header className="flex flex-col md:flex-row md:items-center justify-between gap-6 pb-6 border-b border-white/5">
                <div>
                    <h1 className="text-3xl font-bold tracking-tight mb-1">Minhas <span className="text-[var(--color-primary-gold)]">Avaliações</span></h1>
                    <p className="text-gray-500 text-sm italic">O que os clientes dizem sobre o seu trabalho.</p>
                </div>
                <div className="flex items-center gap-3">
                    <div className="flex bg-black/40 p-2 rounded-2xl border border-white/5 items-center gap-4 px-6">
                        <div className="flex gap-1">
                            {[1, 2, 3, 4, 5].map(i => <Star key={i} size={14} className="text-[var(--color-primary-gold)] fill-current" />)}
                        </div>
                        <span className="text-xl font-black text-white">4.9</span>
                        <span className="text-[9px] text-gray-600 font-bold uppercase tracking-widest border-l border-white/10 pl-4">128 REVIEWS</span>
                    </div>
                </div>
            </header>

            {/* Filter Bar */}
            <div className="flex items-center justify-between bg-[var(--color-dark-card)] border border-[var(--color-dark-border)] rounded-2xl p-4 px-8 shadow-xl">
                <div className="flex items-center gap-6 overflow-x-auto no-scrollbar py-1">
                    {['TODAS', '5 ESTRELAS', '4 ESTRELAS', '3 ESTRELAS'].map((filter, i) => (
                        <button key={filter} className={`text-[10px] font-black uppercase tracking-[0.2em] whitespace-nowrap transition-colors ${i === 0 ? 'text-[var(--color-primary-gold)]' : 'text-gray-600 hover:text-white'}`}>
                            {filter}
                        </button>
                    ))}
                </div>
                <button className="flex items-center gap-2 text-[10px] font-black uppercase tracking-widest text-gray-500 hover:text-white transition-colors">
                    RECENTES <ChevronDown size={14} />
                </button>
            </div>

            {/* Ratings List */}
            <div className="grid grid-cols-1 gap-6">
                {ratings.map((rating) => (
                    <div key={rating.id} className="group relative bg-[var(--color-dark-card)] border border-[var(--color-dark-border)] rounded-[3rem] p-10 shadow-2xl transition-all duration-500 hover:border-[var(--color-primary-gold)]/20 hover:-translate-y-1">
                        <div className="absolute top-0 right-0 w-32 h-32 bg-[var(--color-primary-gold)]/5 rounded-full blur-[40px] -mr-16 -mt-16 opacity-0 group-hover:opacity-100 transition-opacity" />

                        <div className="flex flex-col md:flex-row gap-8 relative z-10">
                            {/* Left Side: Avatar & Stars */}
                            <div className="flex md:flex-col items-center gap-4 shrink-0 md:text-center">
                                <div className="w-16 h-16 rounded-2xl bg-black border border-white/5 flex items-center justify-center text-gray-600 group-hover:text-[var(--color-primary-gold)] transition-colors">
                                    <User size={32} strokeWidth={1} />
                                </div>
                                <div>
                                    <div className="flex gap-1 md:justify-center mb-1">
                                        {[...Array(5)].map((_, i) => (
                                            <Star key={i} size={10} className={`${i < rating.stars ? 'text-[var(--color-primary-gold)] fill-current' : 'text-gray-800'}`} />
                                        ))}
                                    </div>
                                    <p className="text-[10px] text-gray-600 font-bold uppercase tracking-widest">{rating.date}</p>
                                </div>
                            </div>

                            {/* Right Side: Content */}
                            <div className="flex-1 space-y-4">
                                <div className="flex items-center justify-between">
                                    <h4 className="text-xl font-bold text-white tracking-tight">{rating.client}</h4>
                                    <span className="flex items-center gap-2 px-3 py-1 bg-white/5 rounded-lg text-[9px] font-black uppercase tracking-widest text-gray-500 italic">
                                        <Scissors size={10} className="text-[var(--color-primary-gold)]" /> {rating.service}
                                    </span>
                                </div>
                                <div className="relative pt-2">
                                    <Quote className="absolute -top-1 -left-2 w-8 h-8 text-white/5 -z-0" />
                                    <p className="text-gray-400 italic text-sm leading-relaxed relative z-10">"{rating.comment}"</p>
                                </div>
                                <div className="pt-4 flex items-center gap-4 border-t border-white/5">
                                    <button className="flex items-center gap-2 text-[9px] font-black uppercase tracking-widest text-gray-700 hover:text-emerald-500 transition-colors group/btn">
                                        <ThumbsUp size={12} className="group-hover/btn:-translate-y-0.5 transition-transform" /> ACHOU ÚTIL?
                                    </button>
                                    <button className="flex items-center gap-2 text-[9px] font-black uppercase tracking-widest text-gray-700 hover:text-[var(--color-primary-gold)] transition-colors group/btn">
                                        <MessageCircle size={12} /> RESPONDER
                                    </button>
                                </div>
                            </div>
                        </div>
                    </div>
                ))}
            </div>

            <div className="bg-gradient-to-br from-[var(--color-primary-gold)]/10 to-transparent border border-[var(--color-primary-gold)]/20 rounded-[2.5rem] p-10 flex flex-col md:flex-row items-center justify-between gap-8 shadow-2xl">
                <div className="flex items-center gap-6 text-center md:text-left">
                    <div className="w-16 h-16 bg-[var(--color-primary-gold)] text-black rounded-2xl flex items-center justify-center shadow-[0_0_20px_rgba(212,175,55,0.3)]">
                        <Award size={32} />
                    </div>
                    <div>
                        <h3 className="text-xl font-black text-white italic">Nível de Excelência</h3>
                        <p className="text-xs text-gray-400 mt-1">Você está no top 5% dos barbeiros melhor avaliados este mês!</p>
                    </div>
                </div>
                <Button className="h-14 px-8 rounded-2xl bg-[var(--color-primary-gold)] text-black font-black uppercase text-[10px] tracking-[0.2em] shadow-xl hover:scale-105 transition-transform">
                    VER MEU DASHBOARD RELATÓRIO
                </Button>
            </div>
        </div>
    );
}
